CREATE TABLE timetable_swaps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, requesting_teacher_id BIGINT UNSIGNED NOT NULL, target_teacher_id BIGINT UNSIGNED NOT NULL, swap_date DATE NOT NULL, requesting_class_subject_id BIGINT UNSIGNED NOT NULL, requesting_period_number TINYINT NOT NULL, target_class_subject_id BIGINT UNSIGNED NOT NULL, target_period_number TINYINT NOT NULL, status VARCHAR(30) DEFAULT 'PENDING', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (requesting_teacher_id) REFERENCES teachers(id), FOREIGN KEY (target_teacher_id) REFERENCES teachers(id), FOREIGN KEY (requesting_class_subject_id) REFERENCES class_subjects(id), FOREIGN KEY (target_class_subject_id) REFERENCES class_subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
